CREATE OR REPLACE FUNCTION public.fn_ca_guard_new_satellite_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_abi text; v_target uuid:=COALESCE(NEW.satellite_target_id,NEW.satellite_target);
 v_target_row public.tournaments%ROWTYPE; v_supported boolean;
 v_supported_target boolean;  -- 2026-10-16: a bounty target accepts a feeder
 v_source_diamond boolean;  -- DIAMOND PHASE 9
BEGIN
 IF TG_OP='UPDATE' AND
   (NEW.satellite_target_id,NEW.satellite_target,NEW.is_bounty,NEW.is_pko,NEW.is_mystery_bounty,
    NEW.is_premium_spin,NEW.variant,NEW.tournament_type,NEW.club_id,NEW.union_id)
   IS NOT DISTINCT FROM
   (OLD.satellite_target_id,OLD.satellite_target,OLD.is_bounty,OLD.is_pko,OLD.is_mystery_bounty,
    OLD.is_premium_spin,OLD.variant,OLD.tournament_type,OLD.club_id,OLD.union_id) THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock_shared(530090,1);
 v_abi:=public.fn_ca_lock_mtt_admission_contract();
 -- DIAMOND PHASE 9: ASSETS NEVER CROSS, under every admission contract. A
 -- satellite and its target are the same asset or the row is refused by name.
 v_source_diamond:=EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=NEW.club_id AND c.asset='diamonds');
 IF v_target IS NOT NULL AND EXISTS(SELECT 1 FROM public.tournaments x WHERE x.id=v_target) THEN
  IF v_source_diamond AND NOT public.fn_poker_diamond_tournament(v_target) THEN
   RAISE EXCEPTION 'SATELLITE_DIAMOND_SOURCE_CANNOT_FEED_A_CHIP_TARGET' USING ERRCODE='22023';
  ELSIF NOT v_source_diamond AND public.fn_poker_diamond_tournament(v_target) THEN
   RAISE EXCEPTION 'SATELLITE_CHIP_SOURCE_CANNOT_FEED_A_DIAMOND_TARGET' USING ERRCODE='22023';
  END IF;
 END IF;
 IF v_abi='legacy-capacity-v1' THEN RETURN NEW;END IF;
 IF NEW.satellite_target_id IS NOT NULL AND NEW.satellite_target IS NOT NULL
    AND NEW.satellite_target_id<>NEW.satellite_target THEN
  RAISE EXCEPTION 'SATELLITE_TARGET_POINTER_CONTRADICTION' USING ERRCODE='22023';
 END IF;
 -- Under READ COMMITTED the post-lock query sees a just-committed feeder.
 -- A repeatable snapshot could otherwise permit an incompatible target edit.
 IF current_setting('transaction_isolation')<>'read committed'
    AND (TG_OP='UPDATE' OR v_target IS NOT NULL) THEN
  RAISE EXCEPTION 'SATELLITE_CONTRACT_REQUIRES_READ_COMMITTED' USING ERRCODE='0A000';
 END IF;
 v_supported:=NEW.is_bounty IS FALSE AND NEW.is_pko IS FALSE AND NEW.is_mystery_bounty IS FALSE
   AND NEW.is_premium_spin IS FALSE
   AND lower(btrim(COALESCE(NEW.variant,''))) NOT IN
    ('spin','bounty','progressive','progressive_bounty','pko','mystery','mystery_bounty')
   AND lower(btrim(COALESCE(NEW.tournament_type,''))) NOT IN
    ('spin','bounty','progressive','progressive_bounty','pko','mystery','mystery_bounty');
 -- A satellite is never itself a bounty or Spin (v_supported, the SOURCE
 -- rule). As a TARGET a row needs only known flags, no Spin, and no bounty
 -- on a Diamond event, whose seat transfer has no bounty part (2026-10-16).
 v_supported_target:=NEW.is_bounty IS NOT NULL AND NEW.is_pko IS NOT NULL
   AND NEW.is_mystery_bounty IS NOT NULL AND NEW.is_premium_spin IS FALSE
   AND lower(btrim(COALESCE(NEW.variant,''))) <> 'spin'
   AND lower(btrim(COALESCE(NEW.tournament_type,''))) <> 'spin'
   AND (NOT (NEW.is_bounty OR NEW.is_pko OR NEW.is_mystery_bounty)
        OR NOT v_source_diamond);
 -- DIAMOND PHASE 9: a Diamond row is supported like a chip row; the asset rule
 -- above decides which targets it may feed, and a target fed by a live
 -- satellite may not change its asset.
 IF TG_OP='UPDATE' AND (NOT v_supported_target OR v_target IS NOT NULL
      OR v_source_diamond IS DISTINCT FROM
         EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=OLD.club_id AND c.asset='diamonds')
      OR lower(COALESCE(NEW.variant,''))='satellite' OR upper(COALESCE(NEW.tournament_type,''))='SATELLITE')
   AND EXISTS(SELECT 1 FROM public.tournaments s WHERE (s.format_contract='mtt-v2' OR (s.format_contract='sng-v1' AND public.fn_ca_is_fixed_sng_satellite(to_jsonb(s))))
     AND (s.satellite_target_id=NEW.id OR s.satellite_target=NEW.id) AND s.id<>NEW.id
     AND upper(COALESCE(s.status,'')) NOT IN ('COMPLETED','CANCELLED','CANCELED')) THEN
  RAISE EXCEPTION 'SATELLITE_LIVE_TARGET_CANNOT_BECOME_UNSUPPORTED' USING ERRCODE='22023';
 END IF;
 IF v_target IS NULL AND (lower(COALESCE(NEW.variant,''))='satellite'
    OR upper(COALESCE(NEW.tournament_type,''))='SATELLITE') THEN
  RAISE EXCEPTION 'SATELLITE_NEW_TARGET_REQUIRED' USING ERRCODE='22023';
 END IF;
 IF v_target IS NOT NULL THEN
  IF NOT v_supported THEN RAISE EXCEPTION 'SATELLITE_NEW_SOURCE_UNSUPPORTED' USING ERRCODE='22023';END IF;
  SELECT * INTO v_target_row FROM public.tournaments WHERE id=v_target FOR UPDATE;
  IF NOT FOUND OR NOT (CASE WHEN v_source_diamond  -- DIAMOND PHASE 9
       THEN public.fn_ca_diamond_satellite_target_accepts_new_feeder(v_target)
       ELSE public.fn_ca_satellite_target_accepts_new_feeder(v_target) END)
     OR (NEW.union_id IS NOT NULL AND v_target_row.union_id IS DISTINCT FROM NEW.union_id)
     OR (NEW.union_id IS NULL AND (v_target_row.club_id IS DISTINCT FROM NEW.club_id OR v_target_row.union_id IS NOT NULL)) THEN
   RAISE EXCEPTION 'SATELLITE_NEW_TARGET_UNSUPPORTED' USING ERRCODE='22023';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_guard_tournament_format()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_format text; v_abi text;
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.format_contract IS NOT NULL THEN
      RAISE EXCEPTION 'TOURNAMENT_FORMAT_IS_DATABASE_ASSIGNED' USING ERRCODE='22023';
    END IF;
    v_abi:=public.fn_ca_lock_mtt_admission_contract();
    IF v_abi='unlimited-mtt-v2' AND public.fn_ca_is_new_mtt(to_jsonb(NEW)) THEN
      IF NEW.max_players IS NOT NULL OR COALESCE(NEW.min_players,0)<3 THEN
        RAISE EXCEPTION 'MTT_V2_CAPACITY_NOT_NORMALIZED' USING ERRCODE='23514';
      END IF;
      v_format:='mtt-v2';
    ELSE
      v_format:=public.fn_ca_legacy_tournament_format(to_jsonb(NEW));
    END IF;
    IF v_format IS NULL THEN
      RAISE EXCEPTION 'TOURNAMENT_LEGACY_FORMAT_AMBIGUOUS' USING ERRCODE='23514';
    END IF;
    NEW.format_contract:=v_format;
    RETURN NEW;
  END IF;
  IF NEW.format_contract IS DISTINCT FROM OLD.format_contract THEN
    RAISE EXCEPTION 'TOURNAMENT_FORMAT_IMMUTABLE' USING ERRCODE='55000';
  END IF;
  IF OLD.format_contract='mtt-v2' THEN
    IF NOT public.fn_ca_is_new_mtt(to_jsonb(NEW)) OR NEW.max_players IS NOT NULL
       OR COALESCE(NEW.min_players,0)<3 THEN
      RAISE EXCEPTION 'TOURNAMENT_FORMAT_IDENTITY_CONFLICT' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
  END IF;
  IF public.fn_ca_tournament_format_identity(to_jsonb(NEW))
      IS DISTINCT FROM public.fn_ca_tournament_format_identity(to_jsonb(OLD))
     AND (OLD.format_contract IS NULL
          OR public.fn_ca_legacy_tournament_format(to_jsonb(NEW)) IS DISTINCT FROM OLD.format_contract) THEN
    RAISE EXCEPTION 'TOURNAMENT_FORMAT_IDENTITY_CONFLICT' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_new_tournament_is_unlimited(p_config jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_abi text;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(530090,1);
 v_abi:=public.fn_ca_lock_mtt_admission_contract();
 RETURN v_abi='unlimited-mtt-v2' AND public.fn_ca_is_new_mtt(p_config);
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_normalize_new_mtt_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_unlimited boolean;
BEGIN
 v_unlimited:=public.fn_ca_new_tournament_is_unlimited(to_jsonb(NEW));
 IF TG_OP='INSERT' THEN
  IF v_unlimited THEN
   IF public.fn_entry_purchases_frozen() THEN
    RAISE EXCEPTION 'MTT_CREATION_PLATFORM_FROZEN' USING ERRCODE='55000';
   END IF;
   NEW.max_players:=NULL;
   NEW.min_players:=GREATEST(3,COALESCE(NEW.min_players,3));
   IF COALESCE(NEW.satellite_target_id,NEW.satellite_target) IS NOT NULL
      AND (upper(COALESCE(NEW.tournament_type,'')) IN ('SNG','SPIN')
           OR lower(COALESCE(NEW.variant,'')) IN ('sng','spin')) THEN
    RAISE EXCEPTION 'NEW_SATELLITE_REQUIRES_SCHEDULED_MTT_CONFIG' USING ERRCODE='55000';
   END IF;
  END IF;
 ELSIF OLD.format_contract='mtt-v2' THEN
  IF NOT v_unlimited THEN
   RAISE EXCEPTION 'MTT_V2_REQUIRES_ACTIVE_ADMISSION' USING ERRCODE='55000';
  END IF;
  NEW.max_players:=NULL;
 ELSIF v_unlimited AND OLD.format_contract='mtt-v1' THEN
  -- A now-irrelevant cap edit cannot rewrite an accepted version1 contract.
  NEW.max_players:=OLD.max_players;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_requested_payout_depth(p_value text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v numeric;
BEGIN
  IF p_value IS NULL OR btrim(p_value) !~ '^[0-9]+(\.[0-9]+)?$' THEN RETURN NULL; END IF;
  v := round(btrim(p_value)::numeric, 2);
  RETURN CASE WHEN v > 0 AND v <= 100 THEN v END;
END $function$

CREATE OR REPLACE FUNCTION public.fn_can_create_games(p_club_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_own uuid;
  v_member uuid;
BEGIN
  IF p_club_id IS NULL OR p_user_id IS NULL THEN RETURN false; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.clubs c
     WHERE c.id = p_club_id AND c.lifecycle_status = 'active'
  ) THEN RETURN false; END IF;

  SELECT own_union_id, member_union_id INTO v_own, v_member
    FROM public.fn_club_union_context(p_club_id);
  IF v_own IS NOT NULL THEN
    RETURN EXISTS (SELECT 1 FROM public.unions u WHERE u.id = v_own AND u.owner_id = p_user_id)
        OR EXISTS (SELECT 1 FROM public.union_admins a WHERE a.union_id = v_own AND a.user_id = p_user_id)
        OR public.fn_club_is_staff(p_club_id,p_user_id);
  END IF;
  IF v_member IS NOT NULL THEN
    RETURN EXISTS (SELECT 1 FROM public.unions u WHERE u.id = v_member AND u.owner_id = p_user_id)
        OR EXISTS (SELECT 1 FROM public.union_admins a WHERE a.union_id = v_member AND a.user_id = p_user_id);
  END IF;
  RETURN public.fn_club_is_staff(p_club_id,p_user_id);
END
$function$

CREATE OR REPLACE FUNCTION public.fn_mystery_bounty_creation_document(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_profile text:=coalesce(p_config->>'mysteryBountyProfile','classic');
  v_activation text:=coalesce(p_config->>'mysteryBountyActivation','at_the_money');
  v_value jsonb:=coalesce(p_config->'mysteryBountyActivationValue','null'::jsonb);
  v_pool jsonb:=coalesce(nullif(p_config->'mysteryBountyPoolPercent','null'::jsonb),'50'::jsonb);
  v_top jsonb:=coalesce(nullif(p_config->'mysteryBountyTopPercent','null'::jsonb),'20'::jsonb);
BEGIN
  IF p_config IS NULL OR jsonb_typeof(p_config)<>'object' THEN
    RAISE EXCEPTION 'Invalid mystery bounty configuration' USING ERRCODE='22023';
  END IF;
  IF v_profile NOT IN ('balanced','classic','jackpot') THEN
    RAISE EXCEPTION 'Invalid mystery bounty profile' USING ERRCODE='22023';
  END IF;
  IF v_activation NOT IN ('at_the_money','percent_field','player_count') THEN
    RAISE EXCEPTION 'Invalid mystery bounty activation' USING ERRCODE='22023';
  END IF;
  IF v_activation<>'at_the_money' THEN
    IF jsonb_typeof(v_value)<>'number' THEN
      RAISE EXCEPTION 'Invalid mystery bounty activation value' USING ERRCODE='22023';
    END IF;
    IF v_activation='percent_field' AND ((v_value#>>'{}')::numeric<=0 OR (v_value#>>'{}')::numeric>100) THEN
      RAISE EXCEPTION 'Invalid mystery bounty activation percentage' USING ERRCODE='22023';
    END IF;
    IF v_activation='player_count' AND ((v_value#>>'{}')::numeric<2
       OR (v_value#>>'{}')::numeric>9007199254740991
       OR trunc((v_value#>>'{}')::numeric)<>(v_value#>>'{}')::numeric) THEN
      RAISE EXCEPTION 'Invalid mystery bounty activation player count' USING ERRCODE='22023';
    END IF;
  ELSE
    v_value:='null'::jsonb;
  END IF;
  IF jsonb_typeof(v_pool)<>'number' OR jsonb_typeof(v_top)<>'number' THEN
    RAISE EXCEPTION 'Invalid mystery bounty percentage type' USING ERRCODE='22023';
  END IF;
  IF (v_pool#>>'{}')::numeric<0 OR (v_pool#>>'{}')::numeric>100
     OR trunc((v_pool#>>'{}')::numeric*100)<>(v_pool#>>'{}')::numeric*100
     OR (v_top#>>'{}')::numeric<=0 OR (v_top#>>'{}')::numeric>100 THEN
    RAISE EXCEPTION 'Invalid mystery bounty percentage range' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object('mystery_bounty_profile',v_profile,
    'mystery_bounty_activation',v_activation,'mystery_bounty_activation_value',v_value,
    'mystery_bounty_pool_percent',v_pool,'mystery_bounty_regular_pool_percent',100-(v_pool#>>'{}')::numeric,
    'mystery_bounty_top_percent',v_top);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_tournament_config_refusal(p_config jsonb, p_surface text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_schedule boolean;
  v_type     text;
  v_short    boolean;
  v_stack    numeric;
  v_start    timestamptz;
  v_target   jsonb;
  v_ok       boolean;
  v_total    numeric;
  v_level    jsonb;
  v_sb       numeric;
  v_bb       numeric;
  v_prev_sb  numeric;
  v_prev_bb  numeric;
  v_seen     boolean := false;
  v_variant  text;
  v_hole     int;
  v_deck     int;
  v_seats    numeric;
  v_rebuy    boolean;
  v_late     numeric;
  v_late_min numeric;
  v_buy_in   numeric;
BEGIN
  IF p_surface IS NULL OR p_surface NOT IN ('create', 'schedule') THEN
    RAISE EXCEPTION 'fn_tournament_config_refusal: unknown surface %', p_surface
      USING ERRCODE = '22023';
  END IF;
  IF p_config IS NULL OR jsonb_typeof(p_config) <> 'object' THEN
    RETURN 'invalid_configuration';
  END IF;
  v_schedule := p_surface = 'schedule';

  BEGIN
    v_type := lower(COALESCE(NULLIF(btrim(p_config->>'type'), ''), 'mtt'));
    IF v_schedule AND v_type IN ('hu_sng', 'heads_up') THEN v_type := 'sng'; END IF;
    v_short := v_type IN ('sng', 'spin');

    -- 1. Starting stack: a whole number above zero, for every format.
    v_stack := NULLIF(p_config->>'startingStack', '')::numeric;
    IF v_stack IS NOT NULL AND (v_stack <= 0 OR v_stack <> trunc(v_stack)) THEN
      RETURN 'starting_stack_must_be_positive';
    END IF;

    -- 2. A start in the past is refused, never silently moved. Five minutes of
    --    skew for a device clock that runs slow.
    IF NOT v_schedule THEN
      v_start := NULLIF(p_config->>'startTime', '')::timestamptz;
      IF v_start IS NOT NULL AND v_start < now() - interval '5 minutes' THEN
        RETURN 'start_time_in_past';
      END IF;
    END IF;

    -- 3. A satellite names the event its seats go into.
    IF v_type = 'satellite' THEN
      IF v_schedule THEN
        v_target := COALESCE(p_config->'satelliteTarget', p_config->'satellite_target');
        -- COALESCE: with no target object every jsonb_typeof test is NULL, and
        -- NOT NULL would wave the satellite through.
        v_ok := COALESCE(
                (jsonb_typeof(v_target) = 'string' AND btrim(v_target #>> '{}') <> '')
             OR (jsonb_typeof(v_target) = 'object'
                 AND COALESCE(NULLIF(v_target->>'tournamentId', ''), NULLIF(v_target->>'tournament_id', '')) IS NOT NULL),
                false)
             OR COALESCE(btrim(p_config->>'satelliteTargetId'), '') <> ''
             OR COALESCE(btrim(p_config->>'satellite_target_id'), '') <> ''
             OR COALESCE(btrim(p_config->>'satelliteTargetName'), '') <> '';
      ELSE
        v_ok := COALESCE(btrim(p_config->>'satelliteTargetId'), '') <> '';
      END IF;
      IF NOT v_ok THEN
        RETURN 'satellite_target_required';
      END IF;
    END IF;

    -- 4. Payouts add up to 100, within the governed creator's tolerance of 1.
    IF jsonb_typeof(p_config->'payoutStructure') = 'array'
       AND jsonb_array_length(p_config->'payoutStructure') > 0 THEN
      SELECT COALESCE(SUM((e->>'percentage')::numeric), 0) INTO v_total
        FROM jsonb_array_elements(p_config->'payoutStructure') e;
      IF abs(v_total - 100) > 1 THEN
        RETURN 'payouts_must_total_100';
      END IF;
    END IF;

    -- 5. A Sit And Go or Spin ladder: positive durations, blinds never fall.
    --    Break rows (a flag, or 0/0 blinds) do not take part. A new MTT ladder
    --    is held to the fuller contract by tournaments_new_mtt_blind_contract.
    IF v_short AND jsonb_typeof(p_config->'blindStructure') = 'array' THEN
      FOR v_level IN SELECT value FROM jsonb_array_elements(p_config->'blindStructure') LOOP
        IF jsonb_typeof(v_level) <> 'object' THEN
          RETURN 'invalid_configuration';
        END IF;
        IF NULLIF(v_level->>'durationMinutes', '') IS NOT NULL
           AND (v_level->>'durationMinutes')::numeric <= 0 THEN
          RETURN 'blind_level_duration_invalid';
        END IF;
        v_sb := NULLIF(v_level->>'smallBlind', '')::numeric;
        v_bb := NULLIF(v_level->>'bigBlind', '')::numeric;
        CONTINUE WHEN COALESCE(v_level->>'isBreak', '') = 'true' OR (v_sb = 0 AND v_bb = 0);
        IF v_seen AND (v_sb < v_prev_sb OR v_bb < v_prev_bb) THEN
          RETURN 'blind_structure_must_not_decrease';
        END IF;
        v_prev_sb := v_sb;
        v_prev_bb := v_bb;
        v_seen := true;
      END LOOP;
    END IF;

    -- 6. No more seats at a table than one deck can deal: the deck, less one
    --    board, over the hole cards each seat takes (VariantRules.maxSeatsFor).
    v_variant := lower(btrim(COALESCE(p_config->>'gameVariant', 'NLH')));
    v_hole := CASE
      WHEN v_variant IN ('plo4', 'plo8', 'flo8') THEN 4
      WHEN v_variant = 'plo5' THEN 5
      WHEN v_variant = 'plo6' THEN 6
      WHEN v_variant = 'pineapple' THEN 3
      ELSE 2 END;
    v_deck := CASE WHEN v_variant LIKE 'short%' THEN 36 ELSE 52 END;
    IF v_schedule AND v_type = 'spin' THEN
      v_seats := 3;
    ELSE
      v_seats := round(NULLIF(p_config->>'tableSize', '')::numeric);
      IF v_seats IS NULL THEN
        v_seats := CASE
          WHEN v_schedule AND v_short
            THEN COALESCE(round(NULLIF(p_config->>'maxPlayers', '')::numeric), 2)
          ELSE 9 END;
      END IF;
      v_seats := LEAST(10, GREATEST(2, v_seats));
    END IF;
    IF v_seats > (v_deck - 5) / v_hole THEN
      RETURN 'table_size_exceeds_deck';
    END IF;

    -- 7. A rebuy or re-entry needs a late registration window to be sold in.
    IF v_schedule THEN
      v_rebuy := COALESCE(p_config->>'isRebuy', '') = 'true'
              OR COALESCE(p_config->>'rebuy', '') = 'true'
              OR COALESCE(p_config->>'isReentry', '') = 'true'
              OR v_type IN ('rebuy', 'reentry', 'mtt_rebuy', 'mtt_reentry');
      v_late := CASE
        WHEN v_short THEN 0
        WHEN NOT (p_config ? 'lateRegistrationLevels') THEN 8
        ELSE COALESCE(NULLIF(p_config->>'lateRegistrationLevels', '')::numeric, 0) END;
      v_late_min := 0;
    ELSE
      v_rebuy := COALESCE((p_config->>'isRebuy')::boolean, false)
              OR COALESCE((p_config->>'isReentry')::boolean, false);
      v_late := CASE WHEN v_short THEN 0
        ELSE COALESCE(NULLIF(p_config->>'lateRegistrationLevels', '')::numeric, 0) END;
      v_late_min := COALESCE(NULLIF(p_config->>'lateRegistrationMinutes', '')::numeric, 0);
    END IF;
    v_buy_in := COALESCE(NULLIF(p_config->>'buyIn', '')::numeric, 0);
    IF v_rebuy
       AND NOT (v_buy_in = 0 AND NOT v_short)   -- a Free Buy event has its own levels
       AND v_late <= 0 AND v_late_min <= 0 THEN
      RETURN 'rebuy_requires_late_registration';
    END IF;
  EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range
      OR invalid_datetime_format OR datetime_field_overflow THEN
      RETURN 'invalid_configuration';
  END;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_tournaments_creation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_paid int;
BEGIN
  IF public.fn_ca_new_tournament_is_unlimited(to_jsonb(NEW)) THEN
    RETURN NEW; -- The earlier normalizer and final recorded-format constraint own NULL.
  END IF;
  IF COALESCE(NEW.max_players, 0) <= 0 THEN
    RAISE EXCEPTION
      'tournament guard: max_players must be positive (got %) - a tournament with no seats can never start',
      NEW.max_players
      USING ERRCODE = '23514';
  END IF;

  IF NEW.payout_structure IS NOT NULL
     AND jsonb_typeof(NEW.payout_structure::jsonb) = 'array' THEN
    v_paid := jsonb_array_length(NEW.payout_structure::jsonb);
    IF v_paid > NEW.max_players THEN
      RAISE EXCEPTION
        'tournament guard: % paid places for % seats - more places than players who can enter',
        v_paid, NEW.max_players
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_lock_mtt_admission_contract()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_abi text;
BEGIN
  SELECT abi INTO v_abi FROM public.ca_mtt_admission_contract WHERE singleton FOR SHARE;
  IF NOT FOUND OR v_abi NOT IN ('legacy-capacity-v1','unlimited-mtt-v2') THEN
    RAISE EXCEPTION 'MTT_ADMISSION_CONTRACT_MISSING_OR_UNKNOWN' USING ERRCODE='55000';
  END IF;
  RETURN v_abi;
END $function$

CREATE OR REPLACE FUNCTION public.fn_club_union_context(p_club_id uuid)
 RETURNS TABLE(own_union_id uuid, member_union_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_union boolean;
  v_union_id uuid;
  v_own      uuid;
BEGIN
  own_union_id := NULL;
  member_union_id := NULL;

  IF p_club_id IS NULL THEN
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT COALESCE(c.is_union, false), c.union_id
    INTO v_is_union, v_union_id
    FROM clubs c
   WHERE c.id = p_club_id;

  IF NOT FOUND THEN
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_is_union OR v_union_id = p_club_id
     OR EXISTS (SELECT 1 FROM unions u WHERE u.id = p_club_id) THEN
    v_own := p_club_id;
    v_union_id := NULL;
  END IF;

  IF v_own IS NULL AND v_union_id IS NULL THEN
    SELECT uc.union_id INTO v_union_id
      FROM union_clubs uc
     WHERE uc.club_id = p_club_id
       AND uc.union_id <> p_club_id
     LIMIT 1;
  END IF;

  own_union_id := v_own;
  member_union_id := v_union_id;
  RETURN NEXT;
END;
$function$
